 144              phase = 'cross';
 145              committedCross = true;
 146              refX = gateX + 0.35;
 147            }
 148  
 149            const ex = Math.abs(gateX - alignDist - p.x);
 150            const ey = Math.abs(gateY - p.y);
 151            const ez = Math.abs(gateZ - p.z);
 152            const spd = Math.hypot(velX, velY, velZ);
 153            const predY = p.y + velY * 0.20 + 0.5 * accY * 0.14 * 0.14;
 154            const predZ = p.z + velZ * 0.20 + 0.5 * accZ * 0.14 * 0.14;
 155            const gustOk = Math.abs(fastDz - slowDz) < 1.25 && Math.abs(fastDy - slowDy) < 1.25;
 156            if (
 157              ex < 0.105 &&
 158              ey < 0.080 &&
 159              ez < 0.055 &&
 160              spd < 0.28 &&
 161              Math.abs(velZ) < 0.14 &&
 162              Math.abs(predY - gateY) < 0.105 &&
 163              Math.abs(predZ - gateZ) < 0.070 &&
 164              gustOk
 165            ) {
 166              settle++;
 167            } else {
 168              settle = Math.max(0, settle - 1);
 169            }
 170            if (settle >= 10) {
 171              phase = 'cross';
 172              intX = 0;
 173            }
 174          }
 175  
 176          if (phase === 'cross') {
 177            targetX = gateX + 0.32;
 178            targetY = gateY;
 179            targetZ = gateZ;
 180            // 6. Predictive cross abort with stopping-distance check
 181            const dx = gateX - p.x;
 182            if (dx > 0.01) {
 183              const vxPos = Math.max(0, velX);
 184              const dStop = vxPos * 0.065 + (vxPos * vxPos) / 7.5 + 0.035;
 185  
 186              const vxEff = Math.max(velX, 0.30);
 187              const tau = clamp(dx / vxEff, 0.04, 0.34);
 188              const tauA = Math.min(tau, 0.17);
 189              const ty = velY * accY < 0 ? Math.min(tau, -velY / accY) : tau;
 190              const tz = velZ * accZ < 0 ? Math.min(tau, -velZ / accZ) : tau;
 191              const tya = velY * accY < 0 ? ty : tauA;
 192              const tza = velZ * accZ < 0 ? tz : tauA;
 193              const predY = p.y + velY * ty + 0.5 * accY * tya * tya;
 194              const predZ = p.z + velZ * tz + 0.5 * accZ * tza * tza;
 195              const curY = Math.abs(p.y - gateY);
 196              const curZ = Math.abs(p.z - gateZ);
 197              const unsafe =
 198                curY > 0.150 ||
 199                curZ > 0.080 ||
 200                Math.abs(predY - gateY) > 0.160 ||
 201                Math.abs(predZ - gateZ) > 0.085;
 202  
 203              if (unsafe && dx > dStop) {
 204                phase = 'align';
 205                settle = 0;
 206                intX = 0;
 207                targetX = gateX - alignDist;
 208                refX = Math.min(refX, targetX - 0.05);
 209              } else if (dx <= dStop) {
 210                committedCross = true;
 211                refX = Math.max(refX, p.x + 0.25);
 212              }
 213            }
 214          }
 215        } else {
 216          // 7. Ramp pad descent
 217          const pad = obs.pad.centre;
 218          const hErr = Math.hypot(pad.x - p.x, pad.z - p.z);
 219          const hSpd = Math.hypot(velX, velZ);
 220          if (phase === 'pad_align') {
 221            if (hErr < 0.135 && hSpd < 0.26 && Math.abs(p.y - padY) < 0.18) {
 222              phase = 'descend';
 223            }
 224          }
 225          if (phase === 'descend') {
 226            if (hErr < 0.115 && hSpd < 0.32) {
 227              const rate = p.y > 0.26 ? 0.46 : 0.22;
 228              padY = Math.max(0.02, padY - rate * dt);
 229            } else if (hErr > 0.128) {
 230              padY = clamp(Math.max(padY, p.y) + 0.35 * dt, 0.24, 0.50);
 231              intY = Math.max(0, intY);
 232            }
 233          }
 234          targetX = pad.x;
 235          targetY = padY;
 236          targetZ = pad.z;
 237        }
 238  
 239        // 4. Smooth ref filter
 240        const rdx = targetX - refX;
 241        const rdy = targetY - refY;
 242        const rdz = targetZ - refZ;
 243        const rDist = Math.hypot(rdx, rdy, rdz);
 244        const maxSpeed = phase === 'cross' ? 1.15 : 2.05;
 245        const alphaRef = phase === 'cross' ? 0.12 : 0.10;
 246        const stepScale = rDist > 1e-6 ? Math.min(alphaRef, (maxSpeed * dt) / rDist) : alphaRef;
 247        const refVx = (rdx * stepScale) / dt;
 248        const refVy = (rdy * stepScale) / dt;
 249        const refVz = (rdz * stepScale) / dt;
 250        refX += rdx * stepScale;
 251        refY += rdy * stepScale;
 252        refZ += rdz * stepScale;
 253  
 254        // 3. Yaw + local pos integrals
 255        if (airborne) {
 256          yawInt = clamp(yawInt + a.yaw * dt, -0.6, 0.6);
 257          if (Math.abs(targetX - p.x) < 0.35 && phase !== 'cross') {
 258            intX = clamp(intX + (targetX - p.x) * dt, -0.45, 0.45);
 259          } else {
 260            intX *= 0.96;
 261          }
 262          if (Math.abs(targetY - p.y) < 0.35) {
 263            intY = clamp(intY + (targetY - p.y) * dt, -0.45, 0.45);
 264          } else {
 265            intY *= 0.96;
 266          }
 267          if (Math.abs(targetZ - p.z) < 0.35) {
 268            intZ = clamp(intZ + (targetZ - p.z) * dt, -0.45, 0.45);
 269          } else {
 270            intZ *= 0.96;
 271          }
 272        } else if (p.y <= 0.095) {
 273          intY = Math.max(0, intY);
 274        }
 275  
 276        const distX = slowDx + 0.85 * (fastDx - slowDx);
 277        const distY = slowDy + 0.55 * (fastDy - slowDy);
 278        const distZ = slowDz + 0.85 * (fastDz - slowDz);
 279  
 280        const ex = refX - p.x;
 281        const ey = refY - p.y;
 282        const ez = refZ - p.z;
 283  
 284        const kpx = 5.2, kdx = 3.8, kix = 1.8;
 285        const kpz = committedCross ? 7.2 : 5.8;
 286        const kdz = committedCross ? 4.6 : 4.1;
 287        const kiz = 2.0;
 288        const kpy = committedCross ? 7.0 : 6.0;
 289        const kdy = 4.0, kiy = 2.2;
 290  
 291        const axCmd = clamp(
 292          kpx * ex + kdx * (0.35 * refVx - velX) + kix * intX + dragGain * velX - distX,
 293          -4.5,
 294          4.5
 295        );
 296        const azCmd = clamp(
 297          kpz * ez + kdz * (0.35 * refVz - velZ) + kiz * intZ + dragGain * velZ - distZ,
 298          -4.5,
 299          4.5
 300        );
 301        const ayCmd = clamp(
 302          kpy * ey + kdy * (0.35 * refVy - velY) + kiy * intY + dragGain * velY - distY,
 303          -4.2,
 304          4.6
 305        );
 306  
 307        const ayTotal = Math.max(2.0, g + ayCmd);
 308        const bodyAx = cy * axCmd - sy * azCmd;
 309        const bodyAz = sy * axCmd + cy * azCmd;
 310  
 311        let maxTilt = 0.48;
 312        if (targetIndex === 3 && p.y < 0.18) {
 313          const hErr = Math.hypot(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z);
 314          maxTilt = p.y < 0.105 && hErr < 0.135 ? 0.13 : 0.165;
 315        }
 316  
 317        const pitch = clamp(Math.atan2(bodyAx, ayTotal), -maxTilt, maxTilt);
 318        const roll = clamp(Math.atan2(-bodyAz, Math.hypot(ayTotal, bodyAx)), -maxTilt, maxTilt);
 319  
 320        const tiltCos = Math.max(0.65, Math.cos(a.roll) * Math.cos(a.pitch));
 321        let thrust = clamp(ayTotal / (accGain * tiltCos), 0, 1);
 322  
 323        if (
 324          targetIndex === 3 &&
 325          phase === 'descend' &&
 326          p.y <= 0.088 &&
 327          Math.hypot(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) < 0.125 &&
 328          Math.hypot(velX, velZ) < 0.32
 329        ) {
 330          thrust = Math.min(thrust, 0.18);
 331        }
 332  
 333        lastThrust = thrust;
 334        const yawRate = clamp(-3.2 * a.yaw - 2.0 * yawInt - 0.25 * r.yaw, -2, 2);
 335  
 336        actionOut.thrust = thrust;
 337        actionOut.roll = roll;
 338        actionOut.pitch = pitch;
 339        actionOut.yawRate = yawRate;
 340        return actionOut;
 341      },
 342    };
 343  }
